@push('scripts')<script>$(function(){var tableElement=$('#landed-cost-table'),filters=$('#landed-cost-filters'),text=$.fn.dataTable.render.text(),statuses={DRAFT:'app-status-neutral',SUBMITTED:'app-status-warning',APPROVED:'app-status-info',POSTED:'app-status-success',VOID:'app-status-danger'};var table=tableElement.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:tableElement.data('url'),data:function(data){data.date_from=$('#lc-filter-date-from').val();data.date_to=$('#lc-filter-date-to').val();data.status=$('#lc-filter-status').val();}},order:[[1,'desc']],buttons:[window.erpExcelButton(tableElement)],columns:[{data:'document_number',render:function(v,type,row){return type==='display'?'<a class="fw-semibold link-primary" href="'+text.display(row.show_url)+'">'+text.display(v)+'</a><small class="text-secondary d-block">'+text.display(row.allocations_count+' allocation')+'</small>':v;}},{data:'business_date',render:text.display},{data:'basis_label',render:text.display},{data:'total_amount',className:'text-end',render:$.fn.dataTable.render.number(',','.',2)},{data:'status_label',render:function(v,type,row){return type==='display'?'<span class="badge '+(statuses[row.status]||'app-status-neutral')+'">'+text.display(v)+'</span>':row.status;}},{data:null,orderable:false,searchable:false,className:'text-end text-nowrap',render:function(v,type,row){if(type!=='display')return '';var actions=['<a class="btn btn-sm btn-app-soft" href="'+text.display(row.show_url)+'" title="ดูรายละเอียด" aria-label="ดูรายละเอียด"><i class="bx bx-file-find" aria-hidden="true"></i></a>'];if(row.print_url)actions.push('<a class="btn btn-sm btn-app-soft" target="_blank" href="'+text.display(row.print_url)+'" title="พิมพ์" aria-label="พิมพ์"><i class="bx bx-printer" aria-hidden="true"></i></a>');if(row.delete_url)actions.push('<button type="button" class="btn btn-sm btn-app-danger js-delete" data-url="'+text.display(row.delete_url)+'" title="ลบร่าง" aria-label="ลบร่าง"><i class="bx bx-trash" aria-hidden="true"></i></button>');return actions.join(' ');}}]}));filters.on('change','input,select',function(){table.ajax.reload();});filters.on('click','.js-reset',function(){filters.find('input,select').val('');table.ajax.reload();});window.erpAjaxDelete({button:'.js-delete',reload:'#landed-cost-table',title:'ลบร่าง Landed Cost?',text:'เอกสารร่างจะถูกลบและไม่สามารถกู้คืนได้',confirmButtonText:'ลบร่าง',cancelButtonText:'กลับ'});});</script>@endpush
